ESTILO_ARBOL_MAESTRO:
QTreeWidget {
    background-color: #1a1a1a;
    border: 1px solid #2d2d2d;
    color: #dcdcdc;
    font-size: 10px;
}
QTreeWidget::item:selected {
    background-color: #007acc;
    color: #ffffff;
    font-weight: bold;
}
QTreeWidget::item:hover:!selected {
    background-color: #262626;
}

ESTILO_BOTON_VANO:
QPushButton {
    background-color: #282828;
    border: 1px solid #3d3d3d;
    border-radius: 4px;
    font-size: 9px;
    color: #cccccc;
    padding: 2px 4px;
}
QPushButton:checked {
    background-color: #007acc;
    border-color: #007acc;
    color: #ffffff;
    font-weight: bold;
}
QPushButton:hover:!checked {
    background-color: #333333;
    color: #ffffff;
}

ESTILO_MICRO_HEADER:
QFrame#VDOMicroHeader {
    background-color: #1e1e1e;
    border-top: 1px solid #2d2d2d;
    border-bottom: 1px solid #2d2d2d;
    padding: 1px 4px;
}
QLabel {
    color: #888888;
    font-size: 10px;
    font-weight: bold;
}
QDoubleSpinBox {
    background-color: #282828;
    color: #00d4ff;
    border: 1px solid #3d3d3d;
    border-radius: 3px;
    padding: 1px 2px;
    font-size: 10px;
    font-weight: bold;
}
QDoubleSpinBox:focus {
    border-color: #007acc;
    background-color: #333333;
}
